#include <SparkFun_Qwiic_Humidity_AHT20.h>

/*--------------------------- Device Status ------------------------------*/
bool AHT20::begin(TwoWire &wirePort)
{
    _i2cPort = &wirePort; //Grab the port the user wants to communicate on

    _deviceAddress = AHT20_DEFAULT_ADDRESS; //We had hoped the AHT20 would support two addresses but it doesn't seem to

    if (isConnected() == false)
        return false;

    //Wait 40 ms after power-on before reading temp or humidity. Datasheet pg 8
    delay(40);

    //Check if the calibrated bit is set. If not, init the sensor.
    if (isCalibrated() == false)
    {
        //Send 0xBE0800
        initialize();

        //Immediately trigger a measurement. Send 0xAC3300
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        //This calibration sequence is not completely proven. It's not clear how and when the cal bit clears
        //This seems to work but it's not easily testable
        if (isCalibrated() == false)
        {
            return (false);
        }
    }

    //Check that the cal bit has been set
    if (isCalibrated() == false)
        return false;

    //Mark all datums as fresh (not read before)
    sensorQueried.temperature = true;
    sensorQueried.humidity = true;

    return true;
}

//Ping the AHT20's I2C address
//If we get a response, we are correctly communicating with the AHT20
bool AHT20::isConnected()
{
    _i2cPort->beginTransmission(_deviceAddress);
    if (_i2cPort->endTransmission() == 0)
        return true;

    //If IC failed to respond, give it 20ms more for Power On Startup
    //Datasheet pg 7
    delay(20);

    _i2cPort->beginTransmission(_deviceAddress);
    if (_i2cPort->endTransmission() == 0)
        return true;

    return false;
}

/*------------------------ Measurement Helpers ---------------------------*/

uint8_t AHT20::getStatus()
{
    _i2cPort->requestFrom(_deviceAddress, (uint8_t)1);
    if (_i2cPort->available())
        return (_i2cPort->read());
    return (0);
}

//Returns the state of the cal bit in the status byte
bool AHT20::isCalibrated()
{
    return (getStatus() & (1 << 3));
}

//Returns the state of the busy bit in the status byte
bool AHT20::isBusy()
{
    return (getStatus() & (1 << 7));
}

bool AHT20::initialize()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_initialize);
    _i2cPort->write((uint8_t)0x08);
    _i2cPort->write((uint8_t)0x00);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

bool AHT20::triggerMeasurement()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_measure);
    _i2cPort->write((uint8_t)0x33);
    _i2cPort->write((uint8_t)0x00);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

//Loads the
void AHT20::readData()
{
    //Clear previous data
    sensorData.temperature = 0;
    sensorData.humidity = 0;

    if (_i2cPort->requestFrom(_deviceAddress, (uint8_t)6) > 0)
    {
        _i2cPort->read(); // Read and discard state

        uint32_t incoming = 0;
        incoming |= (uint32_t)_i2cPort->read() << (8 * 2);
        incoming |= (uint32_t)_i2cPort->read() << (8 * 1);
        uint8_t midByte = _i2cPort->read();

        incoming |= midByte;
        sensorData.humidity = incoming >> 4;

        sensorData.temperature = (uint32_t)midByte << (8 * 2);
        sensorData.temperature |= (uint32_t)_i2cPort->read() << (8 * 1);
        sensorData.temperature |= (uint32_t)_i2cPort->read() << (8 * 0);

        //Need to get rid of data in bits > 20
        sensorData.temperature = sensorData.temperature & ~(0xFFF00000);

        //Mark data as fresh
        sensorQueried.temperature = false;
        sensorQueried.humidity = false;
    }
}

//Triggers a measurement if one has not been previously started, then returns false
//If measurement has been started, checks to see if complete.
//If not complete, returns false
//If complete, readData(), mark measurement as not started, return true
bool AHT20::available()
{
    if (measurementStarted == false)
    {
        triggerMeasurement();
        measurementStarted = true;
        return (false);
    }

    if (isBusy() == true)
    {
        return (false);
    }

    readData();
    measurementStarted = false;
    return (true);
}

bool AHT20::softReset()
{
    _i2cPort->beginTransmission(_deviceAddress);
    _i2cPort->write(sfe_aht20_reg_reset);
    if (_i2cPort->endTransmission() == 0)
        return true;
    return false;
}

/*------------------------- Make Measurements ----------------------------*/

float AHT20::getTemperature()
{
    if (sensorQueried.temperature == true)
    {
        //We've got old data so trigger new measurement
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        readData();
    }

    //From datasheet pg 8
    float tempCelsius = ((float)sensorData.temperature / 1048576) * 200 - 50;

    //Mark data as old
    sensorQueried.temperature = true;

    return tempCelsius;
}

float AHT20::getHumidity()
{
    if (sensorQueried.humidity == true)
    {
        //We've got old data so trigger new measurement
        triggerMeasurement();

        delay(75); //Wait for measurement to complete

        uint8_t counter = 0;
        while (isBusy())
        {
            delay(1);
            if (counter++ > 100)
                return (false); //Give up after 100ms
        }

        readData();
    }

    //From datasheet pg 8
    float relHumidity = ((float)sensorData.humidity / 1048576) * 100;

    //Mark data as old
    sensorQueried.humidity = true;

    return relHumidity;
}

#include <cmath>

#include "pch.h"
#include "GPSInstrument.h"
#include "defines.h"

/// <summary>
/// Function Built with basic GitHub coding tools.
/// </summary>
/// <param name="initialLat"></param>
/// <param name="initialLong"></param>
/// <param name="speed"></param>
/// <param name="orientation"></param>
/// <param name="time"></param>
/// <returns></returns>
std::pair<double, double> GPSInstrument::calculateNewPosition(double speed, double orientation, double time) {
	// Convert latitude and longitude from degrees to radians
	double latRad = _lastLatitude * M_PI / 180.0;
	double longRad = _lastLongitude * M_PI / 180.0;

	// Calculate the distance traveled
	double distance = speed * time; // distance in meters

	// Calculate the new latitude
	double newLatRad = asin(sin(latRad) * cos(distance / dEARTH_RADIUS) +
		cos(latRad) * sin(distance / dEARTH_RADIUS) * cos(orientation));

	// Calculate the new longitude
	double newLongRad = longRad + atan2(sin(orientation) * sin(distance / dEARTH_RADIUS) * cos(latRad),
		cos(distance / dEARTH_RADIUS) - sin(latRad) * sin(newLatRad));

	// Convert the new latitude and longitude from radians to degrees
	double newLat = newLatRad * 180.0 / M_PI;
	double newLong = newLongRad * 180.0 / M_PI;

	return std::make_pair(newLat, newLong);
}

/// <summary>
/// Get a new location based on the current location, speed, and orientation.
/// </summary>
/// <param name="zSpeed">Positive: elevating, Negative: falling</param>
/// <param name="speed"></param>
/// <param name="orientation"></param>
/// <returns></returns>
Location GPSInstrument::GetNewLocation(double zSpeed, double speed, double orientation)
{
	// Maybe called from multiple threads.
	//     i.e. Reporting thread and the move to destination thread.
	std::lock_guard<std::mutex> lockTime(_mutexTime);

	Location location;
	std::time_t currentTime = Utils::GetCurrentUnixLocalTime();
	std::pair<double, double> newLocation = calculateNewPosition(speed, orientation, (double)(currentTime - _lastTime));

	_lastTime = currentTime;
	location.Latitude = newLocation.first;
	location.Longitude = newLocation.second;
	location.Altitude = _lastAltitude + (zSpeed * (double)(currentTime - _lastTime));

	_lastLatitude = location.Latitude;
	_lastLongitude = location.Longitude;
	_lastAltitude = location.Altitude;

	return location;
}

Location GPSInstrument::GetLastLocation()
{
	Location location;
	location.Latitude = _lastLatitude;
	location.Longitude = _lastLongitude;
	location.Altitude = _lastAltitude;
	return location;
}	

void GPSInstrument::SetLastLocation(double latitude, double longitude, double altitude)
{
	_lastLatitude = latitude;
	_lastLongitude = longitude;
	_lastAltitude = altitude;
	_lastTime = Utils::GetCurrentUnixLocalTime();
}

#include "FaceDetector.hpp"

/* declaration for function in giflib_to_opencv.cpp to convert
   gif images to a image file that can be used in opencv */
cv::Mat imread_gif(const std::string& filename, const int flags);

int FaceDetector::loadCascade()
{
    if (!faceHaarCascade_.load(HAAR_CASCADE_PATH))
    {
        std::cerr << "ERROR: Failed to load Haar Cascade from " << HAAR_CASCADE_PATH << std::endl;
        return -1; // failure
    }
    return 0; // success
}

int FaceDetector::loadImage(std::string imagePath)
{
    imagePath_ = imagePath;

    std::string fileExtension;
    if (imagePath.find_last_of(".") != std::string::npos)
    {
        fileExtension = imagePath.substr(imagePath.find_last_of(".")+1);
        for(unsigned int i = 0; i < fileExtension.length(); ++i)
        {
            fileExtension[i] = tolower(fileExtension[i]);
        }
    }

    // use correct read function based on file extension
    if ((fileExtension == "jpg") || (fileExtension == "jpeg"))
    {
        image_ = cv::imread(imagePath);
    }
    else if (fileExtension == "png")
    {
        image_ = cv::imread(imagePath);
    }
    else if (fileExtension == "gif")
    {
        /* use gif_lib to load gif file */
        int error = 0;
        GifFileType* gifFile = DGifOpenFileName(imagePath.c_str(), &error); // open gif

        if (!gifFile || (error != 0))
        {
            std::cerr << "ERROR: Could not open gif - " << GifErrorString(error) << std::endl;
            return -2; // failure
        }

        if (DGifSlurp(gifFile) != GIF_OK) // read gif contents into memory structure
        {
            std::cerr << "ERROR: Could not load gif - " << GifErrorString(error) << std::endl;
            return -2; // failure
        }

        const int width = gifFile->Image.Width;
        const int height = gifFile->Image.Height;
        image_ = cv::Mat(cv::Size(width, height), CV_8UC3);

        GifColorType *colorMap = gifFile->SColorMap->Colors;
        SavedImage *img = &gifFile->SavedImages[0];

        auto *ptr = image_.ptr<cv::Vec3b>();
		for (int i = 0; i < width * height; i++, ptr++) {
			const GifColorType &color = colorMap[img->RasterBits[i]];
			*ptr = cv::Vec3b(color.Red, color.Green, color.Blue);
		}
		cvtColor(image_, image_, CV_RGB2BGR);

        DGifCloseFile(gifFile, &error);
    }
    else
    {
        std::cerr << "ERROR: Unrecognized file extension on " << imagePath << std::endl;
        return -1; // failure
    }

    // verify that the image was loaded
    if (image_.empty())
    {
        std::cerr << "ERROR: Failed to load image file " << imagePath << std::endl;
        return -2; // failure
    }

    return 0; // success!
}

int FaceDetector::detectFaces()
{
    if (image_.empty())
    {
        std::cerr << "ERROR: Cannot detect faces; image_ not loaded" << std::endl;
        return -1; // failure
    }

    // convert image to grayscale
    cv::Mat imageGrayScale;
    cv::cvtColor(image_, imageGrayScale, cv::COLOR_BGR2GRAY);
	cv::equalizeHist(imageGrayScale, imageGrayScale);

    // use haar cascade to detect faces
    faceHaarCascade_.detectMultiScale(imageGrayScale, faces_, 1.1, 2, 0 | cv::CASCADE_SCALE_IMAGE, cv::Size(250, 250));

    return faces_.size(); // number of faces detected
}

void FaceDetector::displayImage()
{
    if (image_.empty())
    {
        std::cerr << "ERROR: Cannot display image_; image_ not loaded" << std::endl;
        return; // failure
    }

    for (int i = 0; i < faces_.size(); i++)
	{
		cv::Point center(faces_[i].x + faces_[i].width / 2, faces_[i].y + faces_[i].height / 2);
		cv::ellipse(image_, center, cv::Size(faces_[i].width / 2, faces_[i].height / 2), 0, 0, 360, cv::Scalar(0, 255, 0), 10, 8, 0);
	}

    // scale image to fit within 1280x720 window
    shrinkImage(1280, 720);

    // create a window for display
	cv::namedWindow("Face Detector", cv::WINDOW_AUTOSIZE); 
	cv::imshow("Face Detector", image_);
    cv::waitKey(0);
}

void FaceDetector::saveJSON()
{
    if (imagePath_.empty())
    {
        std::cerr << "ERROR: Cannot save JSON; imagePath_ not available" << std::endl;
        return; // failure
    }

    Json::Value result;
	Json::StreamWriterBuilder builder;
	std::ofstream outFile;

    // populate the JSON fields
	result["countFaces"] = faces_.size();
    char absolutePath [PATH_MAX + 1];
    result["imageLocation"] = realpath(imagePath_.c_str(), absolutePath);

    // create output file in same directory as image
    std::string outFileName = imagePath_ + ".json";
	outFile.open(outFileName);
	builder.newStreamWriter()->write(result, &outFile);
	outFile.close();

    std::cout << "Saved " << outFileName << std::endl;
}

void FaceDetector::shrinkImage(int maxWidth, int maxHeight)
{
    if (image_.empty())
    {
        std::cerr << "ERROR: Cannot scale image_; image_ not loaded" << std::endl;
        return; // failure
    }

    // scale image_ to fit within maxWidth x maxHeight
    cv::Size s = image_.size();
    if ((s.width/s.height) > (maxWidth/maxHeight)) // scale based on width
    {
        cv::resize(image_, image_,
                   cv::Size(maxWidth, (s.height * maxWidth / s.width)));
    }
    else // scale based on height
    {
        cv::resize(image_, image_,
                   cv::Size((s.width * maxHeight / s.height), maxHeight));
    }
}

#ifndef CONVERSION_HPP
#define CONVERSION_HPP

#include <pcl/point_cloud.h>
#include <pcl/point_types.h>
#include <pcl/io/pcd_io.h>
#include <pcl/filters/voxel_grid.h>
#include <pcl/point_types_conversion.h>
#include <pcl_conversions/pcl_conversions.h>
#include <teaser/geometry.h>

template<typename T>
void pcl2teaser(const pcl::PointCloud<T> &pcl_raw, teaser::PointCloud &cloud) {
    cloud.clear();
    for (const auto &pt: pcl_raw.points) {
        cloud.push_back({pt.x, pt.y, pt.z});
    }
}

template<typename T>
sensor_msgs::PointCloud2 cloud2msg(pcl::PointCloud<T> cloud, std::string frame_id = "map") {
    sensor_msgs::PointCloud2 cloud_ROS;
    pcl::toROSMsg(cloud, cloud_ROS);
    cloud_ROS.header.frame_id = frame_id;
    return cloud_ROS;
}

void xyzi2xyz(pcl::PointCloud<pcl::PointXYZI>::Ptr XYZI, pcl::PointCloud<pcl::PointXYZ>::Ptr XYZ) {
    (*XYZ).points.resize((*XYZI).size());
    for (size_t i = 0; i < (*XYZI).points.size(); i++) {
        (*XYZ).points[i].x = (*XYZI).points[i].x;
        (*XYZ).points[i].y = (*XYZI).points[i].y;
        (*XYZ).points[i].z = (*XYZI).points[i].z;
    }
}

template<typename T>
void pcl2eigen(const pcl::PointCloud<T> &pcl_raw, Eigen::Matrix<double, 3, Eigen::Dynamic> &cloud) {
    int N = pcl_raw.points.size();
    cloud.resize(3, N);
    for (int i = 0; i < N; ++i) {
        cloud.col(i) << pcl_raw.points[i].x, pcl_raw.points[i].y, pcl_raw.points[i].z;
    }
}

template<typename T>
void eigen2pcl(const Eigen::Matrix<double, 3, Eigen::Dynamic> &src, pcl::PointCloud<T> &cloud) {
    int num_pc = src.cols();
    T   pt_tmp;
    if (!cloud.empty()) cloud.clear();
    for (int i = 0; i < num_pc; ++i) {
        pt_tmp.x = src(0, i);
        pt_tmp.y = src(1, i);
        pt_tmp.z = src(2, i);
        cloud.points.emplace_back(pt_tmp);
    }
}

