std::vector<std::string> get_intersection( const std::vector<std::string>& vec1,const std::vector<std::string>& vec2 )
{
	std::vector<std::string> intersection;
	for( const auto& w : vec1 )
	{
		if( vector_contains_word( vec2,w ) )
		{
			intersection.push_back( w );
		}
	}
	return intersection;
}

std::vector<int> fill_buckets( const std::string& word )
{
	std::vector<int> buckets( 26,0 );
	for( char c : word )
	{
		buckets[c - 'a']++;
	}
	return buckets;
}

int score_match( const std::string& word1,const std::string& word2 )
{
	const auto buckets1 = fill_buckets( word1 );
	const auto buckets2 = fill_buckets( word2 );

	int score = 0;
	for( int i = 0; i < 26; i++ )
	{
		score += std::min( buckets1[i],buckets2[i] );
	}

	for( int i = 0; i < 5; i++ )
	{
		if( word1[i] == word2[i] )
		{
			score++;
		}
	}

	return score;
}

int main()
{
	std::vector<std::string> five_words;	
	{
		std::ifstream five_word_file( "sgb-words.txt" );
		for( std::string line; std::getline( five_word_file,line ); )
		{
			if( line.empty() )
			{
				continue;
			}
			five_words.push_back( line );
		}
	}

	std::vector<std::string> freq_words;
	{
		std::ifstream freq_word_file( "20k.txt" );
		for( std::string line; std::getline( freq_word_file,line ); )
		{
			if( line.empty() )
			{
				continue;
			}
			freq_words.push_back( line );
		}
	}

	freq_words.resize( 2000 );

	auto filtered_words = get_intersection( five_words,freq_words );

	std::mt19937 rng( std::random_device{}() );
	std::uniform_int_distribution<int> dist( 0,filtered_words.size() - 1 );
	const std::string target = filtered_words[dist( rng )];

	while( true )
	{
		std::cout << "Guess a five letter word: ";
		std::string guess;
		std::getline( std::cin,guess );

		for( auto& c : guess )
		{
			c = std::tolower( c );
		}

		if( guess.size() != 5 )
		{
			std::cout << "I said FIVE letter word, asshole." << std::endl;
			continue;
		}

		if( !vector_contains_word( five_words,guess ) )
		{
			std::cout << guess << "? That isn't even a fucking word." << std::endl;
			continue;
		}

		const int score = score_match( guess,target );
		if( score == 10 )
		{
			std::cout << "You did it. Wow." << std::endl;
			break;
		}
		else
		{
			std::cout << "Nah that ain't it. I'll give you " << score << " points for effort though (retard)." << std::endl;
			continue;
		}
	}

	std::cin.clear();
	std::cin.ignore( std::numeric_limits<std::streamsize>::max(),'\n' );
	std::cin.get();
	return 0;
}

